INSERT INTO bd_accounts (account_name,tier,account_type,city,address,phone,decision_maker_title,priority,notes,status,anneli_covisit_status)
SELECT n.account_name,n.tier,n.account_type,n.city,n.address,n.phone,n.decision_maker_title,n.priority,n.notes,'cold','not_yet' FROM new_data n
WHERE NOT EXISTS (
  SELECT 1 FROM bd_accounts b
  WHERE LOWER(b.account_name) = LOWER(n.account_name)
    AND COALESCE(LOWER(b.city),'') = COALESCE(LOWER(n.city),'')
);